#include <pybind11/pybind11.h>
#include <torch/extension.h>
#include "acl/acl.h"
#include "torch_npu/csrc/core/npu/NPUStream.h"
#include "gather_v2_tiling.h"
extern "C" void gather_v2_do_fp16(uint32_t,void*,uint8_t*,uint8_t*,uint8_t*,uint8_t*);
namespace gather_v2_ext {
using LF=void(*)(uint32_t,void*,uint8_t*,uint8_t*,uint8_t*,uint8_t*);
pybind11::tuple run_gather_v2(const at::Tensor &x, const at::Tensor &indices, int64_t dim) {
    TORCH_CHECK(dim==0,"only dim=0 supported"); TORCH_CHECK(x.dim()==2&&indices.dim()==1,"shape");
    TORCH_CHECK(x.scalar_type()==at::kHalf,"fp16 only"); TORCH_CHECK(x.is_contiguous(),"contiguous");
    auto idx=indices.to(at::kInt).contiguous();
    const auto M=static_cast<int32_t>(idx.sizes()[0]), N=static_cast<int32_t>(x.sizes()[1]);
    const int32_t mNum=(M+DEFAULT_BLOCK_M-1)/DEFAULT_BLOCK_M;
    const int32_t uc=std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES,mNum);
    const int32_t tpc=(mNum+uc-1)/uc;
    at::Tensor y=at::empty({M,N},x.options());
    at::Tensor tc=at::empty({static_cast<long>(sizeof(GatherV2KernelTiling))},at::device(at::kCPU).dtype(at::kByte));
    auto *t=reinterpret_cast<GatherV2KernelTiling*>(tc.data_ptr());
    t->M=M; t->N=N; t->blockM=DEFAULT_BLOCK_M; t->usedCoreNum=uc; t->tasksPerCore=tpc;
    auto tn=tc.to(at::kPrivateUse1); auto stm=c10_npu::getCurrentNPUStream().stream(false);
    gather_v2_do_fp16(uc,stm,
        static_cast<uint8_t*>(const_cast<void*>(x.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(idx.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(y.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(tn.storage().data())));
    return pybind11::make_tuple(y);
}}
PYBIND11_MODULE(_gather_v2_ext, m) { m.def("run_gather_v2",&gather_v2_ext::run_gather_v2,""); }

