#include "gather_v2_kernel.h"
extern "C" __global__ __aicore__ void gather_v2_custom_fp16(GM_ADDR x,GM_ADDR idx,GM_ADDR y,GM_ADDR t){
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_2); AscendC::TPipe p;
    GatherV2Kernel<half> k; k.Init(x,idx,y,t,&p); k.Process();
}
extern "C" void gather_v2_do_fp16(uint32_t d,void* s,uint8_t* x,uint8_t* idx,uint8_t* y,uint8_t* t){
    gather_v2_custom_fp16<<<d,nullptr,s>>>(x,idx,y,t);
}
